import{c as e,Q as r,j as o,m as t}from"./chunks/framework.btqkto0n.js";const _=JSON.parse('{"title":"知识框架","description":"","frontmatter":{},"headers":[],"relativePath":"guide/knowledge-framework.md","filePath":"guide/knowledge-framework.md"}'),i={name:"guide/knowledge-framework.md"};function n(l,a,h,d,s,p){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="知识框架" tabindex="-1">知识框架 <a class="header-anchor" href="#知识框架" aria-label="Permalink to &quot;知识框架&quot;">​</a></h1><p>这个知识库按由浅入深的八个大类维护，新增知识点先归类，再写卡片。</p><h2 id="_1-ai-基础认知" tabindex="-1">1. AI 基础认知 <a class="header-anchor" href="#_1-ai-基础认知" aria-label="Permalink to &quot;1. AI 基础认知&quot;">​</a></h2><p>入门必看，小白第一课。覆盖人工智能、机器学习、深度学习、大模型、生成式 AI、AIGC、弱 AI / 强 AI、判别式 AI vs 生成式 AI，以及训练、微调、推理、算力、数据集、参数、Token 等基础名词。</p><h2 id="_2-主流大模型体系" tabindex="-1">2. 主流大模型体系 <a class="header-anchor" href="#_2-主流大模型体系" aria-label="Permalink to &quot;2. 主流大模型体系&quot;">​</a></h2><p>重点板块。覆盖 GPT、Claude、Gemini、Image 2、国内主流模型、对话模型、文生图、文生视频、多模态模型，以及 API、插件、Function Call、上下文窗口、幻觉等实用概念。</p><h2 id="_3-aigc-应用细分" tabindex="-1">3. AIGC 应用细分 <a class="header-anchor" href="#_3-aigc-应用细分" aria-label="Permalink to &quot;3. AIGC 应用细分&quot;">​</a></h2><p>围绕文生图、文生视频、数字人和文本办公展开。文生图重点记录 DALL·E、Midjourney、Stable Diffusion、GPT Image 2、扩散模型、自回归模型、提示词、反向提示词、图生图、扩图、风格迁移和评估指标。</p><h2 id="_4-ai-配套技术" tabindex="-1">4. AI 配套技术 <a class="header-anchor" href="#_4-ai-配套技术" aria-label="Permalink to &quot;4. AI 配套技术&quot;">​</a></h2><p>连接命令行、部署和工具链。覆盖 Node、Python、环境变量、npm、brew、pip、Git、FFmpeg、终端指令、进程管理、前端库、Python AI 库、本地部署、Docker、网页托管、端口和内网穿透。</p><h2 id="_5-前端-网页搭建" tabindex="-1">5. 前端 &amp; 网页搭建 <a class="header-anchor" href="#_5-前端-网页搭建" aria-label="Permalink to &quot;5. 前端 &amp; 网页搭建&quot;">​</a></h2><p>服务这个知识库网站本身。覆盖 Vue、React、VitePress、Hugo、HTML、CSS、卡片布局、配色、响应式和图标组件。</p><h2 id="_6-数据-存储" tabindex="-1">6. 数据 &amp; 存储 <a class="header-anchor" href="#_6-数据-存储" aria-label="Permalink to &quot;6. 数据 &amp; 存储&quot;">​</a></h2><p>AI 必备底层。覆盖 MySQL、PostgreSQL、Redis、MongoDB、Elasticsearch、基础 SQL、缓存概念和数据存取逻辑。</p><h2 id="_7-ai-行业-场景应用" tabindex="-1">7. AI 行业 &amp; 场景应用 <a class="header-anchor" href="#_7-ai-行业-场景应用" aria-label="Permalink to &quot;7. AI 行业 &amp; 场景应用&quot;">​</a></h2><p>记录设计、办公、教育、电商、影视、工业等行业落地，也记录 AI 提效技巧、免费工具合集和避坑指南。</p><h2 id="_8-进阶常识" tabindex="-1">8. 进阶常识 <a class="header-anchor" href="#_8-进阶常识" aria-label="Permalink to &quot;8. 进阶常识&quot;">​</a></h2><p>覆盖安全合规、AI 内容版权、隐私风险、内容风控、LoRA、RAG、Agent、MCP、Hook 等进阶概念。</p>',18)])])}const m=e(i,[["render",n]]);export{_ as __pageData,m as default};
